heroSpec.cssSketch:
/* v-editorial.css, after the FINE TUNE block. Every rule under html[data-v="editorial"].story.pfilm; html.film never carries pfilm. */
html[data-v="editorial"].story.pfilm .stage{padding-top:0}
html[data-v="editorial"].story.pfilm .band--hero{position:relative;min-height:var(--pf-run,350svh);padding-top:calc(var(--hdr-h) + 10svh)}
html[data-v="editorial"].story.pfilm .band--hero .band__in{position:relative;z-index:1}
/* site.js moves #hero to be .band--hero's first child while pfilm is on, and back before #sky when it goes off */
html[data-v="editorial"].story.pfilm .hero{display:block;position:sticky;top:0;z-index:0;height:100vh;height:100svh;margin:0 calc(var(--gut) * -1) -100svh;background:transparent;overflow:hidden;pointer-events:none;opacity:var(--pf-film,1)}
html[data-v="editorial"].story.pfilm .hero.off{visibility:hidden}
html[data-v="editorial"].story.pfilm .hero__frame{position:absolute;left:50%;top:12svh;width:100vw;height:calc(100vw * 750 / 720);transform:translateX(-50%) scale(var(--pf-zoom,1));transform-origin:50% 50%;background:url("hero-still.jpg") 100% 50% / 185% auto no-repeat;-webkit-mask-image:linear-gradient(180deg,transparent 0,#000 10%,#000 90%,transparent 100%);mask-image:linear-gradient(180deg,transparent 0,#000 10%,#000 90%,transparent 100%)}
html[data-v="editorial"].story.pfilm .hero__film{position:absolute;inset:0;width:100%;height:100%;display:block;opacity:1}
html[data-v="editorial"].story.pfilm .hero__soft{position:absolute;inset:-4%;width:108%;height:108%;display:block;opacity:var(--pf-soft,1)}  /* 32x33 canvas made by site.js; the upscale is the blur */
html[data-v="editorial"].story.pfilm .hero::after{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(10,10,10,.92) 0,rgba(10,10,10,.90) 60svh,rgba(10,10,10,.60) 74svh,rgba(10,10,10,.34) 100%);opacity:calc(.28 + .72 * var(--pf-scrim,1))}
html[data-v="editorial"].story.pfilm .hero__video,
html[data-v="editorial"].story.pfilm .hero__pulses,
html[data-v="editorial"].story.pfilm .hero__ring,
html[data-v="editorial"].story.pfilm .act--still,
html[data-v="editorial"].story.pfilm .band:not(.band--hero) .band__in::before{display:none}
html[data-v="editorial"].story.pfilm .band{padding:clamp(40px,7vh,64px) 0}
html[data-v="editorial"].story.pfilm .hero__snake{position:absolute;inset:0;width:100%;height:100%;overflow:visible}   /* the birth segment, viewport space, made by site.js */
html[data-v="editorial"].story.pfilm .snake{position:absolute;left:0;top:0;width:100%;height:100%;z-index:4;pointer-events:none;overflow:visible}   /* page space, made by site.js, viewBox = .stage px */
html[data-v="editorial"].story.pfilm .snake .thread--glow{stroke-width:9px;opacity:.16}
html[data-v="editorial"].story.pfilm .snake .thread--body{stroke-width:2.6px}
html[data-v="editorial"].story.pfilm .snake .thread--core{stroke:#FFF6E8;stroke-width:.8px;opacity:.35}
html[data-v="editorial"].story.pfilm .snake__tip{position:absolute;left:0;top:0;width:12vh;height:12vh;margin:-6vh 0 0 -6vh;border-radius:50%;pointer-events:none;background:radial-gradient(circle,rgba(255,250,240,.55) 0%,rgba(255,208,150,.16) 30%,rgba(255,208,150,0) 66%)}
/* the two story-wide overflow fixes (issues 1 and 2) go under @media (max-width:760px){ html[data-v="editorial"].story ... } */
